/* repères du corps : T(le long du dos, vers l'avant) et H(repère de la tête), comme dans drawFig */
const mhBody = (J, F) => {
  const HS = F.look && F.look.child ? 1.4 : 1.12;
  return {
    T: (al, ac) => [J.hip[0] + J.up[0] * al + J.fw[0] * ac, J.hip[1] + J.up[1] * al + J.fw[1] * ac],
    H: (x, y) => [J.head[0] + (J.hf[0] * x - J.hu[0] * y) * HS, J.head[1] + (J.hf[1] * x - J.hu[1] * y) * HS]
  };
};
