  const bands = o.short ? [[lo + 0.02, lo + 0.032]] : [[lo + 0.022, lo + 0.038], [lo + 0.05, lo + 0.06], [0.235, 0.25]];
  for (const [a0, a1] of bands) P.fill(Ms([T(a0, back + 0.004), T(a0, front), T(a1, front), T(a1, back + 0.004)]), st, { noKnock: true });
  if (det) for (let i = 1; i <= 2; i++) P.line(Ms([T(0.25, -0.1 + i * 0.05), T(lo + 0.08, back + 0.01 + i * 0.07)]), lw * 0.45);
